'use strict';
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=(n,c='RUB')=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:c,maximumFractionDigits:c==='RUB'?0:2}).format(n), date=x=>new Date(x).toLocaleDateString('ru-RU');
let stored={};try{stored=JSON.parse(localStorage.getItem('checkpoint')||'{}')}catch{}
let s={platform:'Все',regions:['US','PL','TR','JP','BR'],wishlist:[],owned:[],hidden:[],compare:[],targets:{},theme:'system',view:'grid',presets:[],...stored};
let data, filter={sale:false,max:'',discount:0,genre:'',hideOwned:false,sort:'discount',section:'all'}, detailStore='', detailRegion='US',period='all',demo=false,search='',opener;
const plural=(n,one,few,many)=>n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;
const flags={US:'🇺🇸',PL:'🇵🇱',TR:'🇹🇷',JP:'🇯🇵',BR:'🇧🇷'}, platforms=['Все','Nintendo','PS5','Xbox','Steam'];
const save=()=>{try{localStorage.setItem('checkpoint',JSON.stringify(s))}catch{toast('Не удалось сохранить настройки браузера')}};
const reg=id=>data.regions.find(r=>r[0]===id)?.[1]||id;
const offers=(g,p=s.platform,regions=s.regions)=>g.offers.filter(o=>(p==='Все'||o.store===p)&&regions.includes(o.region)).sort((a,b)=>a.rub-b.rub);
const game=id=>data.games.find(g=>g.id===id), btn=(label,action,extra='')=>`<button data-action="${action}" ${extra}>${label}</button>`;
const image=g=>`<img src="${esc(g.image)}" alt="${esc(g.name)}" loading="lazy" referrerpolicy="no-referrer">`;
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function theme(){document.documentElement.dataset.theme=s.theme==='system'?(matchMedia('(prefers-color-scheme:dark)').matches?'dark':'light'):s.theme}theme();matchMedia('(prefers-color-scheme:dark)').addEventListener('change',theme);
function header(){const route=location.hash;$('#header').innerHTML=`<div class="header-main"><a class="brand" href="#">checkpoint<span>↘</span></a><nav aria-label="Главное меню"><a class="${!route?'active':''}" href="#">Обзор</a><a class="${route==='#catalog'?'active':''}" href="#catalog">Каталог</a><a class="${route==='#wishlist'?'active':''}" href="#wishlist">Мои игры <small>${s.wishlist.length}</small></a></nav>${btn('<span>⌕</span> Поиск игр, студий, жанров <kbd>/</kbd>','search','class="search-button" aria-haspopup="dialog"')}<select id="theme" aria-label="Тема сайта">${[['system','◐ Авто'],['light','☀ Светлая'],['dark','☾ Тёмная']].map(([v,n])=>`<option value="${v}" ${s.theme===v?'selected':''}>${n}</option>`).join('')}</select><a href="#account" class="avatar" aria-label="Личный кабинет">${esc((s.profileName||'Я').slice(0,1).toUpperCase())}</a></div><div class="header-filter"><div class="platforms">${platforms.map((p,i)=>btn(`<i class="dot p${i}"></i>${p==='Все'?'Все платформы':p}`,`platform:${p}`,`class="${s.platform===p?'active':''}" aria-pressed="${s.platform===p}"`)).join('')}</div><div class="filter-buttons">${btn(`◎ Регионы <strong>${s.regions.length}</strong>⌄`,'regions','aria-haspopup="dialog"')}${btn('☷ Фильтры'+(filter.max||filter.genre||filter.sale||filter.discount||filter.hideOwned?' •':''),'filters','aria-haspopup="dialog"')}<span class="currency-note">₽ <span>· USD · местная</span></span></div></div>`;$('#theme').onchange=e=>{s.theme=e.target.value;save();theme()}}
function card(g,os=offers(g)){if(!os.length)return '';const o=os[0];return `<article class="game"><a class="game-art" href="#game/${g.id}">${image(g)}${o.discount?`<span class="discount">−${o.discount}%</span>`:''}<span class="platform-tag">${esc(o.store)}</span></a><div class="game-body"><div class="game-genre">${esc(g.genre.split(' · ')[0])}</div><a class="game-title" href="#game/${g.id}" title="${esc(g.name)}">${esc(g.name)}</a><div class="price"><strong>≈ ${money(o.rub)}</strong>${o.initial>o.amount?`<del>${money(o.rub*o.initial/o.amount)}</del>`:''}</div><div class="local-price">≈ ${money(o.usd,'USD')} <span>· ${money(o.amount,o.currency)}</span></div><div class="game-region">${flags[o.region]} ${reg(o.region)} <a href="#game/${g.id}">${new Set(os.map(x=>x.region)).size} рег. ↗</a></div></div><div class="card-actions">${btn(s.wishlist.includes(g.id)?'♥ В желаемом':'♡ Желаемое',`wish:${g.id}`,`aria-pressed="${s.wishlist.includes(g.id)}" aria-label="Желаемое: ${esc(g.name)}"`)}${btn('⇄',`compare:${g.id}`,`aria-label="Сравнить ${esc(g.name)}" aria-pressed="${s.compare.includes(g.id)}"`)}${btn('⋯',`quick:${g.id}`,`aria-label="Действия: ${esc(g.name)}"`)}</div></article>`}
function list(){let a=data.games.map(g=>({g,os:offers(g)})).filter(({g,os})=>os.length&&!s.hidden.includes(g.id));const route=location.hash;if(route==='#wishlist')a=a.filter(({g})=>s.wishlist.includes(g.id));if(route==='#collection')a=a.filter(({g})=>s.owned.includes(g.id));if(filter.hideOwned)a=a.filter(({g})=>!s.owned.includes(g.id));a=a.filter(({g,os})=>(!filter.sale||os[0].discount>0)&&(!filter.max||os[0].rub<=+filter.max)&&os[0].discount>=+filter.discount&&(!filter.genre||g.genre.includes(filter.genre)));if(filter.section==='budget')a=a.filter(({os})=>os[0].rub<=1000);if(filter.section==='sales')a=a.filter(({os})=>os[0].discount>0);a.sort((a,b)=>filter.sort==='price'?a.os[0].rub-b.os[0].rub:filter.sort==='name'?a.g.name.localeCompare(b.g.name):filter.sort==='saving'?spread(b.os)-spread(a.os):(b.os[0].discount||0)-(a.os[0].discount||0));return a}
const spread=os=>os.length?Math.max(...os.map(o=>o.rub))-os[0].rub:0;
function empty(){return `<div class="empty"><span>⌕</span><h2>Пока ничего не нашлось</h2><p>Попробуйте другие регионы или платформу. В личные списки игры добавляются кнопкой на карточке.</p>${btn('Сбросить фильтры','reset','class="primary"')}<a href="#catalog">Открыть каталог →</a></div>`}
function home(){const route=location.hash,isHome=!route||route==='#',personal=['#wishlist','#collection'].includes(route),a=list();const picks=a.filter(x=>x.os[0].discount>0).slice(0,3);$('#app').innerHTML=`${isHome?`<section class="intro"><div><div class="eyebrow"><span class="live-dot"></span> ВАШ СЛЕДУЮЩИЙ CHECKPOINT</div><h1>Хорошие игры.<br><em>Ещё лучше цены.</em></h1><p>Найдите свою игру. Сравните регионы.<br>Поймайте цену, которую ждали.</p><a href="#catalog" class="primary">Найти свою игру ↗</a></div><div class="featured"><div class="section-label">В ФОКУСЕ <span>Снимок ${date(data.fetchedAt)}</span></div>${picks.map(({g,os})=>`<a class="featured-row" href="#game/${g.id}">${image(g)}<div><b>${esc(g.name)}</b><small>${flags[os[0].region]} ${reg(os[0].region)} · ${os[0].store}</small></div><div><strong>${money(os[0].rub)}</strong><span class="green">−${os[0].discount}%</span></div></a>`).join('')||'<p>Для этих регионов скидок пока нет.</p>'}</div></section><a class="telegram-banner" href="#account"><span class="telegram-icon">↗</span><div><strong>Ждать скидку — ваше дело. Следить за ней — наше.</strong><span>Бесплатные уведомления в Telegram · подключение бота позже</span></div><b>Настроить →</b></a>`:''}<div class="section-heading"><div><div class="eyebrow">${personal?'ВАША ИГРОВАЯ ПОЛКА':'ОФИЦИАЛЬНЫЕ МАГАЗИНЫ'}</div><h1>${route==='#wishlist'?'Желаемое':route==='#collection'?'Моя коллекция':isHome?'Найдите выгодный момент':'Каталог игр'}</h1></div><div class="view-toggle">${btn('▦','view:grid',`aria-label="Сетка" aria-pressed="${s.view==='grid'}"`)}${btn('☰','view:list',`aria-label="Список" aria-pressed="${s.view==='list'}"`)}</div></div>${personal?`<div class="tabs"><a class="${route==='#wishlist'?'selected':''}" href="#wishlist">Желаемое · ${s.wishlist.length}</a><a class="${route==='#collection'?'selected':''}" href="#collection">Уже куплены · ${s.owned.length}</a><a href="#account">Ценовые цели ↗</a></div>`:`<div class="tabs">${[['all','Все игры'],['sales','Со скидкой'],['budget','До 1 000 ₽']].map(([v,n])=>btn(n,`section:${v}`,`class="${filter.section===v?'selected':''}"`)).join('')}</div>`}<div class="catalog-toolbar"><span><b>${a.length}</b> ${plural(a.length,'игра','игры','игр')} <span class="muted">· ${s.regions.length} ${plural(s.regions.length,'регион','региона','регионов')} · ${s.platform}</span></span><label>Сортировка <select id="sort">${[['discount','По размеру скидки'],['price','Сначала дешевле'],['saving','Разница между регионами'],['name','По названию']].map(([v,n])=>`<option value="${v}" ${filter.sort===v?'selected':''}>${n}</option>`).join('')}</select></label></div><div class="filter-chips">${filter.max?btn(`До ${money(+filter.max)} ×`,'clear:max'):''}${filter.genre?btn(esc(filter.genre)+' ×','clear:genre'):''}${filter.sale?btn('Только скидки ×','clear:sale'):''}${+filter.discount?btn(`От −${filter.discount}% ×`,'clear:discount'):''}${filter.hideOwned?btn('Без купленных ×','clear:hideOwned'):''}</div><div id="cards" class="grid ${s.view==='list'?'list-view':''}">${a.map(({g,os})=>card(g,os)).join('')||empty()}</div><div class="snapshot-note">◷ Снимок магазинов от ${date(data.fetchedAt)}. Цены могли измениться. <a href="#about">Источники и покрытие ↗</a></div>`;$('#sort').onchange=e=>{filter.sort=e.target.value;home()}}
function shell(title,body,kind=''){opener=document.activeElement;$('#modal').innerHTML=`<div class="modal-content ${kind}"><div class="modal-head"><h2 id="modal-title">${title}</h2>${btn('×','close','class="close" aria-label="Закрыть окно"')}</div>${body}</div>`;if(!$('#modal').open)$('#modal').showModal();document.body.classList.add('modal-open')}
function close(){if($('#modal').open)$('#modal').close();document.body.classList.remove('modal-open');opener?.focus()}
function regions(){shell('Ваши регионы',`<p class="muted">Сравниваем выбранные страны одновременно. На карточке — самое доступное предложение.</p><input id="country-search" type="search" placeholder="Найти страну" aria-label="Найти страну"><div class="region-choices">${data.regions.map(([id,n])=>`<label data-country="${esc(n.toLowerCase())}"><span>${flags[id]} ${n}</span><input name="region" type="checkbox" value="${id}" ${s.regions.includes(id)?'checked':''}></label>`).join('')}</div><p class="muted">Сейчас в снимке 5 стран. Валюту определяет магазин: например, Steam в Турции использует USD.</p><div class="modal-actions">${btn('Выбрать все','regions-all')}${btn('Применить','regions-apply','class="primary"')}</div>`);$('#country-search').oninput=e=>document.querySelectorAll('[data-country]').forEach(l=>l.hidden=!l.dataset.country.includes(e.target.value.toLowerCase()))}
function filters(){const genres=[...new Set(data.games.flatMap(g=>g.genre.split(' · ')))].sort();shell('Точная настройка',`<form id="filters-form"><div class="form-grid"><label>Цена до, ₽<input name="max" type="number" min="0" value="${esc(filter.max)}" placeholder="Без ограничения"></label><label>Скидка от<select name="discount">${[0,25,50,75,90].map(v=>`<option value="${v}" ${+filter.discount===v?'selected':''}>${v}%</option>`).join('')}</select></label></div><label>Жанр<select name="genre"><option value="">Все жанры</option>${genres.map(g=>`<option ${filter.genre===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label><label class="check"><input name="sale" type="checkbox" ${filter.sale?'checked':''}> Только предложения со скидкой</label><label class="check"><input name="hideOwned" type="checkbox" ${filter.hideOwned?'checked':''}> Скрывать уже купленные игры</label><div class="modal-actions">${btn('Сбросить','reset','type="button"')}<button class="primary">Показать игры</button></div></form><hr><div class="section-label">СОХРАНЁННЫЕ НАБОРЫ</div><div class="preset-list">${s.presets.map((p,i)=>btn(esc(p.name),`preset:${i}`)).join('')||'<p class="muted">Сохраните комбинацию фильтров, чтобы вернуться к ней позже.</p>'}</div>${btn('Сохранить текущие фильтры','preset-save')}`);$('#filters-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);filter={...filter,max:f.get('max'),discount:+f.get('discount'),genre:f.get('genre'),sale:f.has('sale'),hideOwned:f.has('hideOwned')};close();location.hash='#catalog';render()}}
function searchModal(){shell('Что будем играть?',`<div class="search-input"><span>⌕</span><input id="search-input" type="search" placeholder="Игра, студия или жанр…" autocomplete="off" aria-label="Поиск игр"></div><div id="search-results"></div>`,'search-modal');$('#search-input').value=search;$('#search-input').oninput=e=>{search=e.target.value;searchResults()};searchResults();$('#search-input').focus()}
function searchResults(){let q=search.toLowerCase().trim();const a=data.games.filter(g=>[g.name,g.genre,g.developer].join(' ').toLowerCase().includes(q));$('#search-results').innerHTML=`<p class="muted">${q?`Найдено ${a.length} · поиск по всем регионам и платформам`:'Начните с этих игр · весь каталог'}</p><div class="search-grid">${(q?a:a.slice(0,6)).map(g=>card(g,offers(g,'Все',data.regions.map(r=>r[0])))).join('')||'<div class="empty">Ничего не найдено. Попробуйте другое название.</div>'}</div>`}
function target(id){const g=game(id),targetPlatform=location.hash==='#game/'+id?detailStore:s.platform,os=offers(g,targetPlatform),o=os[0]||g.offers.find(x=>targetPlatform==='Все'||x.store===targetPlatform)||g.offers[0];shell('Поймать свою цену',`<div class="target-game">${image(g)}<div><b>${esc(g.name)}</b><p class="muted">Сейчас от ≈ ${money(o.rub)}</p></div></div><form id="target-form"><label>Уведомить при цене ниже, ₽<input id="target-value" type="number" required min="0" step="1" value="${s.targets[id]?.amount??Math.round(o.rub*.75)}"></label><div class="presets">${[.75,.5,.25].map(v=>btn(money(Math.round(o.rub*v)),`target-preset:${Math.round(o.rub*v)}`,'type="button"')).join('')}</div><p class="muted">${esc(targetPlatform)} · ${s.regions.map(reg).join(', ')||'Регионы не выбраны'}</p><button class="primary wide">Сохранить цель</button></form><div class="notice">↗ Уведомления бесплатные, через Telegram. Пока сохраняем цель в браузере; отправка появится вместе с ботом.</div>`);$('#target-form').onsubmit=e=>{e.preventDefault();s.targets[id]={amount:+$('#target-value').value,currency:'RUB',platform:targetPlatform,regions:[...s.regions]};if(!s.wishlist.includes(id))s.wishlist.push(id);save();close();render(false);toast('Ценовая цель сохранена')}}
function quick(id){const g=game(id);shell(esc(g.name),`<div class="quick-actions">${btn('♧ Настроить ценовую цель',`target:${id}`)}${btn(s.owned.includes(id)?'✓ Убрать из коллекции':'+ Уже куплена',`owned:${id}`)}${btn('Скрыть из каталога',`hide:${id}`)}<a href="#game/${id}">Открыть страницу игры →</a></div>`)}
function detail(id){const g=game(id);if(!g){$('#app').innerHTML=empty();return}const stores=[...new Set(g.offers.map(o=>o.store))];if(!stores.includes(detailStore))detailStore=stores.includes(s.platform)?s.platform:stores[0];const os=offers(g,detailStore);const all=offers(g,detailStore,data.regions.map(r=>r[0]));if(!all.some(o=>o.region===detailRegion))detailRegion=all[0]?.region;const b=os[0];$('#app').innerHTML=`<div class="breadcrumbs"><a href="#catalog">Каталог</a> / ${esc(g.name)}</div><section class="detail-hero"><div class="detail-image">${image(g)}</div><div><div class="eyebrow">${esc(g.genre)}</div><h1>${esc(g.name)}</h1><p class="muted">${esc(g.developer)} · ${esc(g.release)}</p><div class="tabs">${stores.map(p=>btn(p,`store:${p}`,`class="${detailStore===p?'selected':''}"`)).join('')}</div><div class="detail-price">${b?`<strong>≈ ${money(b.rub)}</strong><span>≈ ${money(b.usd,'USD')} · ${money(b.amount,b.currency)}<small>${flags[b.region]} ${reg(b.region)} · лучшее из выбранных предложений</small></span>`:'Нет предложений в выбранных регионах'}</div><div class="detail-actions">${btn('♧ Отслеживать цену',`target:${id}`,'class="primary"')}${btn(s.wishlist.includes(id)?'♥ В желаемом':'♡ В желаемое',`wish:${id}`)}${btn(s.owned.includes(id)?'✓ Куплена':'+ В коллекцию',`owned:${id}`)}</div></div></section><div class="detail-layout"><div><section class="panel"><div class="section-heading"><h2>Где выгоднее?</h2>${btn('Изменить регионы','regions')}</div><p class="muted">${esc(detailStore)} · стандартное издание · официальные предложения</p><div class="table-wrap"><table><thead><tr><th>Регион</th><th>Цена в рублях</th><th>В долларах</th><th>В магазине</th><th></th></tr></thead><tbody>${os.map((o,i)=>`<tr class="${i===0?'best-row':''}"><td>${flags[o.region]} ${reg(o.region)}${i===0?'<small class="green">Выгоднее в выборке</small>':''}</td><td><b>≈ ${money(o.rub)}</b>${i?`<small>+${money(o.rub-b.rub)}</small>`:''}</td><td>${money(o.usd,'USD')}</td><td>${money(o.amount,o.currency)}${o.discount?`<small class="green">−${o.discount}%</small>`:''}</td><td><a class="store-link" href="${esc(o.url)}" target="_blank" rel="noopener">В магазин ↗</a></td></tr>`).join('')||'<tr><td colspan="5">Для выбранных регионов нет цен. Измените выбор выше.</td></tr>'}</tbody></table></div><p class="fine">Снимок от ${date(data.fetchedAt)} · пересчёт по курсу ЦБ от ${esc(data.fxDate)}. Доступность покупки зависит от региона аккаунта и условий магазина.</p></section><section class="panel"><div class="section-heading"><h2>История цены</h2><select id="chart-region" aria-label="Регион графика">${all.map(o=>`<option value="${o.region}" ${o.region===detailRegion?'selected':''}>${reg(o.region)}</option>`).join('')}</select></div><div class="chart-toolbar"><div class="tabs">${[['30','Месяц'],['90','3 месяца'],['all','Всё время']].map(([v,n])=>btn(n,`period:${v}`,`class="${period===v?'selected':''}"`)).join('')}</div><label class="check"><input id="demo-chart" type="checkbox" ${demo?'checked':''}> Демо графика</label></div><div id="chart"></div></section><section class="panel"><h2>Об игре</h2><p class="description">${esc(g.description)}</p><dl><div><dt>Разработчик</dt><dd>${esc(g.developer)}</dd></div><div><dt>Дата выхода</dt><dd>${esc(g.release)}</dd></div><div><dt>Жанры</dt><dd>${esc(g.genre)}</dd></div></dl><a class="text-link" href="${esc(g.metadataSource)}" target="_blank" rel="noopener">Описание и изображение из официального магазина ↗</a></section></div><aside><section class="panel target-panel"><div class="eyebrow">ВАША ЦЕНА</div><h2>${s.targets[id]?money(s.targets[id].amount):'Не спешите покупать'}</h2><p>Сохраните желаемую цену. Когда подключим бота, он сообщит о подходящей скидке.</p>${btn(s.targets[id]?'Изменить цель':'Задать цену',`target:${id}`,'class="primary wide"')}<span class="free">Бесплатно · Telegram</span></section><section class="panel"><h3>Разница между регионами</h3><strong class="saving">${money(spread(os))}</strong><p class="muted">Между самым дорогим и самым доступным предложением в выбранных регионах.</p></section></aside></div><div class="section-heading"><h2>Ещё в этом жанре</h2></div><div class="grid">${data.games.filter(x=>x.id!==id&&x.genre.split(' · ').some(t=>g.genre.includes(t))).filter(x=>offers(x).length).slice(0,6).map(x=>card(x)).join('')}</div>`;$('#chart-region').onchange=e=>{detailRegion=e.target.value;chart(g)};$('#demo-chart').onchange=e=>{demo=e.target.checked;chart(g)};chart(g)}
function chart(g){let points=data.history.filter(x=>x.game===g.id&&x.store===detailStore&&x.region===detailRegion).map(x=>({date:x.checkedAt,value:x.rub})).sort((a,b)=>new Date(a.date)-new Date(b.date));if(period!=='all')points=points.filter(x=>Date.now()-new Date(x.date)<=+period*86400000);if(demo){const base=g.offers.find(o=>o.store===detailStore&&o.region===detailRegion)?.rub||1000;points=[1.6,1.6,1.25,1.25,1.6,1.45,1.45,1,1,1.3,1,.85].map((v,i)=>({date:new Date(Date.now()-(11-i)*(period==='30'?2:7)*86400000).toISOString(),value:Math.round(base*v)}))}if(!points.length){$('#chart').innerHTML='<div class="empty">За этот период наблюдений нет.</div>';return}const max=Math.max(...points.map(p=>p.value))*1.2,min=Math.min(...points.map(p=>p.value))*.7;const y=v=>160-(v-min)/(max-min||1)*130;const xy=points.map((p,i)=>`${50+i*580/Math.max(points.length-1,1)},${y(p.value)}`);$('#chart').innerHTML=`<div class="chart-note ${demo?'demo-label':''}">${demo?'Демонстрация интерфейса · вымышленные точки, не история магазина':`Реальные наблюдения: ${points.length} · ${reg(detailRegion)} · ${detailStore}`}</div><svg viewBox="0 0 680 205" role="img" aria-label="График цены в рублях"><line x1="50" y1="160" x2="640" y2="160" class="chart-grid"/><line x1="50" y1="90" x2="640" y2="90" class="chart-grid"/><polyline points="${xy.join(' ')}" fill="none" stroke="var(--accent)" stroke-width="3"/>${points.map((p,i)=>`<circle tabindex="0" cx="${50+i*580/Math.max(points.length-1,1)}" cy="${y(p.value)}" r="5" fill="var(--accent)"><title>${date(p.date)}: ${money(p.value)}</title></circle>`).join('')}<text x="50" y="193">${date(points[0].date)}</text><text x="540" y="193">${date(points.at(-1).date)}</text></svg><div class="chart-stats"><span>Минимум в выборке <b>${money(Math.min(...points.map(p=>p.value)))}</b></span><span>Последняя точка <b>${money(points.at(-1).value)}</b></span></div><p class="fine">${demo?'Выключите демо, чтобы вернуться к сохранённым данным.':'Наблюдений пока мало. Это не исторический минимум за всё время.'}</p>`}
function comparePage(){const gs=s.compare.map(game).filter(Boolean);$('#app').innerHTML=`<div class="section-heading"><div><div class="eyebrow">ОДИН ВЗГЛЯД — ВСЕ ЦЕНЫ</div><h1>Сравнение игр</h1></div>${btn('Очистить','compare-clear')}</div><p class="muted">Одна платформа и выбранные регионы. Отсутствие цены означает отсутствие предложения в нашем снимке.</p>${gs.length?`<div class="table-wrap panel"><table class="compare-table"><thead><tr><th>Регион / игра</th>${gs.map(g=>`<th><a href="#game/${g.id}">${image(g)}${esc(g.name)}</a>${btn('Убрать',`compare:${g.id}`)}</th>`).join('')}</tr></thead><tbody>${s.regions.map(r=>`<tr><th>${flags[r]} ${reg(r)}</th>${gs.map(g=>{const o=offers(g,s.platform,[r])[0];return `<td>${o?`<b>${money(o.rub)}</b><small>${money(o.usd,'USD')} · ${money(o.amount,o.currency)}</small><small>${o.store}</small>`:'Нет данных'}</td>`}).join('')}</tr>`).join('')}</tbody></table></div>`:empty()}`}
function tray(){const gs=s.compare.map(game).filter(Boolean);$('#compare-tray').innerHTML=gs.length&&location.hash!=='#compare'?`<div><span>⇄ <b>${gs.length}/4</b> в сравнении</span><span class="tray-titles">${gs.map(g=>esc(g.name)).join(' · ')}</span><a href="#compare" class="primary">Сравнить →</a>${btn('×','compare-clear','aria-label="Очистить сравнение"')}</div>`:''}
function account(){const targets=Object.entries(s.targets).filter(([id])=>game(id));$('#app').innerHTML=`<div class="section-heading"><div><div class="eyebrow">ВАШ CHECKPOINT</div><h1>${s.profileName?'Привет, '+esc(s.profileName):'Личный кабинет'}</h1><p class="muted">Профиль сохраняется на этом устройстве. Без регистрации.</p></div><div class="avatar large">${esc((s.profileName||'Я')[0])}</div></div><div class="stats"><a href="#wishlist"><b>${s.wishlist.length}</b>В желаемом →</a><a href="#collection"><b>${s.owned.length}</b>В коллекции →</a><div><b>${targets.length}</b>Ценовых целей</div></div><div class="two-cols"><section class="panel"><h2>Профиль и предпочтения</h2><form id="profile-form"><label>Ваше имя<input name="name" maxlength="60" value="${esc(s.profileName||'')}" placeholder="Как к вам обращаться?"></label><button class="primary">Сохранить</button></form><hr><h3>Скрытые игры · ${s.hidden.length}</h3><p class="muted">Скрытые игры не показываются в каталоге.</p>${btn('Вернуть скрытые игры','unhide')}${btn('Скачать мои списки','export')}</section><section class="panel telegram-panel"><div class="eyebrow">БЕСПЛАТНО. БЕЗ ПОДПИСКИ.</div><h2>Скидки приходят<br>в Telegram.</h2><p>Выберите события, о которых хотите узнавать.</p><label class="check"><input data-notify="notifyDiscount" type="checkbox" ${s.notifyDiscount!==false?'checked':''}> Любая скидка в желаемом</label><label class="check"><input data-notify="notifyTarget" type="checkbox" ${s.notifyTarget!==false?'checked':''}> Цена достигла моей цели</label>${btn('Посмотреть уведомление','notification-preview','class="primary"')}<p class="fine">Это настройка будущих уведомлений. Бот ещё не подключён, сообщения не отправляются.</p></section></div><section class="panel"><h2>Мои ценовые цели</h2>${targets.map(([id,t])=>`<div class="target-row"><a href="#game/${id}">${esc(game(id).name)}<small>${esc(t.platform)} · ${(t.regions||[]).map(reg).join(', ')}</small></a><strong>${money(t.amount)}</strong>${btn('Изменить',`target:${id}`)}${btn('×',`delete-target:${id}`,`aria-label="Удалить цель ${esc(game(id).name)}"`)}</div>`).join('')||'<p class="muted">Откройте игру и нажмите «Отслеживать цену». Ваши цели появятся здесь.</p>'}</section>`;$('#profile-form').onsubmit=e=>{e.preventDefault();s.profileName=new FormData(e.target).get('name').trim();save();render(false);toast('Профиль сохранён')};document.querySelectorAll('[data-notify]').forEach(el=>el.onchange=()=>{s[el.dataset.notify]=el.checked;save();toast('Настройка сохранена')})}
function about(){$('#app').innerHTML=`<div class="section-heading"><div><div class="eyebrow">ПРОЗРАЧНО О ДАННЫХ</div><h1>Всё, что стоит знать</h1></div></div><div class="two-cols"><section class="panel"><h2>Откуда цены</h2><p>В каталоге ${data.games.length} игры и ${data.games.reduce((n,g)=>n+g.offers.length,0)} предложений. Описания, обложки и цены получены из официальных магазинов. У каждой игры есть ссылка на источник.</p><p>Последнее обновление: ${date(data.fetchedAt)}. Это сохранённый снимок, а не актуальная проверка магазина.</p><p>Покрытие неравномерное: основная часть каталога — Steam; Nintendo, PS5 и Xbox представлены отдельными играми.</p><a href="${esc(data.fxSource)}" target="_blank" rel="noopener">Курсы ЦБ от ${esc(data.fxDate)} ↗</a></section><section class="panel"><h2>Что уже работает</h2><p>Поиск, фильтры, сравнение регионов и игр, желаемое, коллекция, ценовые цели, темы и локальные настройки.</p><h3>Что появится позже</h3><p>Регистрация, синхронизация между устройствами, регулярное обновление цен и отправка уведомлений в Telegram.</p><p>Демонстрационный график включается отдельно и всегда отмечен как вымышленный.</p></section></div>`}
function render(top=false){if(!data)return;header();const h=location.hash;if(h.startsWith('#game/'))detail(h.slice(6));else if(h==='#account')account();else if(h==='#compare')comparePage();else if(h==='#about')about();else home();tray();if(top){window.scrollTo(0,0);$('#header').classList.remove('header-hidden')}}
function mutateList(key,id){s[key]=s[key].includes(id)?s[key].filter(x=>x!==id):[...s[key],id];save()}
function action(a){const [type,...parts]=a.split(':'),v=parts.join(':');switch(type){case'close':close();break;case'search':searchModal();break;case'regions':regions();break;case'regions-all':document.querySelectorAll('[name=region]').forEach(e=>e.checked=true);break;case'regions-apply':{const r=[...document.querySelectorAll('[name=region]:checked')].map(e=>e.value);if(!r.length){toast('Выберите хотя бы один регион');return}s.regions=r;save();close();render();break}case'filters':filters();break;case'platform':s.platform=v;save();render();break;case'section':filter.section=v;home();break;case'view':s.view=v;save();home();break;case'clear':filter[v]=v==='genre'||v==='max'?'':false;render();break;case'reset':filter={sale:false,max:'',discount:0,genre:'',hideOwned:false,sort:'discount',section:'all'};s.platform='Все';s.regions=data.regions.map(r=>r[0]);save();close();render();break;case'wish':mutateList('wishlist',v);render();if($('#search-input'))searchResults();toast(s.wishlist.includes(v)?'Добавлено в желаемое':'Убрано из желаемого');break;case'owned':mutateList('owned',v);close();render();toast(s.owned.includes(v)?'Добавлено в коллекцию':'Убрано из коллекции');break;case'hide':mutateList('hidden',v);close();render();toast('Игра скрыта. Вернуть можно в профиле');break;case'unhide':s.hidden=[];save();render();toast('Игры возвращены');break;case'quick':quick(v);break;case'target':target(v);break;case'target-preset':$('#target-value').value=v;break;case'delete-target':delete s.targets[v];save();render();break;case'compare':if(!s.compare.includes(v)&&s.compare.length>=4){toast('Можно сравнить до 4 игр');return}mutateList('compare',v);render();if($('#search-input'))searchResults();break;case'compare-clear':s.compare=[];save();render();break;case'store':detailStore=v;detail(location.hash.slice(6));break;case'period':period=v;detail(location.hash.slice(6));break;case'preset-save':{const f=$('#filters-form');if(!f.reportValidity())return;const fd=new FormData(f);const current={...filter,max:fd.get('max'),discount:+fd.get('discount'),genre:fd.get('genre'),sale:fd.has('sale'),hideOwned:fd.has('hideOwned')};s.presets.push({name:`${s.platform} · ${current.max?money(+current.max):'без лимита'} · ${current.genre||'все жанры'}`,filter:current,platform:s.platform,regions:[...s.regions]});save();toast('Набор сохранён');filters();break}case'preset':{const p=s.presets[+v];filter={...p.filter};s.platform=p.platform;s.regions=[...p.regions];save();close();location.hash='#catalog';render();break}case'notification-preview':shell('Так будет выглядеть уведомление',`<div class="demo-label">Демонстрация · сообщение не отправлено</div><div class="telegram-message"><b>Checkpoint ↘</b><h3>Ваша игра стала доступнее</h3><p>Целевая цена достигнута. Здесь будут название игры, регион, цена и ссылка на официальный магазин.</p><span class="muted">Только полезные уведомления. Бесплатно.</span></div>`);break;case'export':{const blob=new Blob([JSON.stringify({wishlist:s.wishlist,owned:s.owned,targets:s.targets},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='checkpoint-lists.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Списки выгружены');break}}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action);if(e.target.closest('a[href^="#"]')&&$('#modal').open)close()});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))close()});$('#modal').addEventListener('cancel',e=>{e.preventDefault();close()});document.addEventListener('keydown',e=>{if(e.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement.tagName)){e.preventDefault();searchModal()}});window.addEventListener('hashchange',()=>{close();render(true)});
let previous=window.scrollY,acc=0;window.addEventListener('scroll',()=>{const y=window.scrollY,d=y-previous;acc=Math.sign(d)===Math.sign(acc)?acc+d:d;if(y<120||acc< -8||$('#modal').open)$('#header').classList.remove('header-hidden');else if(acc>35&&!$('#header').contains(document.activeElement))$('#header').classList.add('header-hidden');previous=y},{passive:true});$('#header').addEventListener('focusin',()=>$('#header').classList.remove('header-hidden'));
fetch('catalog.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{data=x;render()}).catch(()=>{$('#app').innerHTML='<div class="empty"><h1>Каталог не загрузился</h1><p>Обновите страницу, чтобы повторить попытку.</p></div>'});
